// Byte-exact checks against vectors generated by the JS reference
// (tools/host/gen-vectors.js).

#include <stdio.h>
#include <string.h>

#include <sodium.h>

#include "../src/crypto.h"
#include "../src/messages.h"
#include "../src/noise.h"
#include "vectors.h"

static int failures = 0;

#define CHECK(cond, name) \
  do { \
    if (cond) printf("ok   %s\n", name); \
    else { \
      printf("FAIL %s\n", name); \
      failures++; \
    } \
  } while (0)

#define CHECK_BYTES(buf, len, vec, name) CHECK((size_t) (len) == sizeof(vec) && memcmp(buf, vec, sizeof(vec)) == 0, name)

static void
seed_keypair (uint8_t pk[32], uint8_t sk[64], uint8_t byte) {
  uint8_t seed[32];
  memset(seed, byte, 32);
  crypto_sign_seed_keypair(pk, sk, seed);
}

static void
test_noise (void) {
  uint8_t i_pk[32], i_sk[64], r_pk[32], r_sk[64], ie_pk[32], ie_sk[64], re_pk[32], re_sk[64];
  seed_keypair(i_pk, i_sk, 0x01);
  seed_keypair(r_pk, r_sk, 0x02);
  seed_keypair(ie_pk, ie_sk, 0x03);
  seed_keypair(re_pk, re_sk, 0x04);

  CHECK(memcmp(r_pk, NOISE_R_PK, 32) == 0, "noise: seed key pair");

  hdht_noise_t a, b;
  hdht_noise_init(&a, true, i_pk, i_sk, r_pk, HDHT_NS_PEER_HANDSHAKE);
  hdht_noise_init(&b, false, r_pk, r_sk, NULL, HDHT_NS_PEER_HANDSHAKE);
  hdht_noise_set_ephemeral(&a, ie_pk, ie_sk);
  hdht_noise_set_ephemeral(&b, re_pk, re_sk);

  uint8_t msg[256], payload[256];

  int n = hdht_noise_send(&a, NOISE_PAYLOAD1, sizeof(NOISE_PAYLOAD1), msg, sizeof(msg));
  CHECK_BYTES(msg, n, NOISE_MSG1, "noise: msg1");

  n = hdht_noise_recv(&b, NOISE_MSG1, sizeof(NOISE_MSG1), payload, sizeof(payload));
  CHECK_BYTES(payload, n, NOISE_PAYLOAD1, "noise: responder decrypts payload1");
  CHECK(memcmp(b.rs, i_pk, 32) == 0, "noise: responder learns initiator key");

  n = hdht_noise_send(&b, NOISE_PAYLOAD2, sizeof(NOISE_PAYLOAD2), msg, sizeof(msg));
  CHECK_BYTES(msg, n, NOISE_MSG2, "noise: msg2");

  n = hdht_noise_recv(&a, NOISE_MSG2, sizeof(NOISE_MSG2), payload, sizeof(payload));
  CHECK_BYTES(payload, n, NOISE_PAYLOAD2, "noise: initiator decrypts payload2");

  CHECK(a.complete && b.complete, "noise: both complete");
  CHECK(memcmp(a.hash, NOISE_HASH, 64) == 0, "noise: handshake hash");
  CHECK(memcmp(a.tx, NOISE_I_TX, 32) == 0 && memcmp(a.rx, NOISE_I_RX, 32) == 0, "noise: initiator split");
  CHECK(memcmp(b.rx, NOISE_I_TX, 32) == 0 && memcmp(b.tx, NOISE_I_RX, 32) == 0, "noise: responder split");

  uint8_t out[32];
  hdht_holepunch_secret(out, a.hash);
  CHECK(memcmp(out, NOISE_HOLEPUNCH_SECRET, 32) == 0, "noise: holepunch secret");
  hdht_stream_id(out, a.hash, true);
  CHECK(memcmp(out, SS_ID_INITIATOR, 32) == 0, "secret-stream: initiator id");
  hdht_stream_id(out, a.hash, false);
  CHECK(memcmp(out, SS_ID_RESPONDER, 32) == 0, "secret-stream: responder id");

  // tampering must fail
  uint8_t bad[sizeof(NOISE_MSG1)];
  memcpy(bad, NOISE_MSG1, sizeof(bad));
  bad[60] ^= 1;
  hdht_noise_t c;
  hdht_noise_init(&c, false, r_pk, r_sk, NULL, HDHT_NS_PEER_HANDSHAKE);
  CHECK(hdht_noise_recv(&c, bad, sizeof(bad), payload, sizeof(payload)) < 0, "noise: rejects tampered msg1");
}

static void
test_messages (void) {
  uint8_t buf[512];

  // noise payloads round trip
  hdht_noise_payload_t p;
  CHECK(hdht_noise_payload_decode(&p, NOISE_PAYLOAD2, sizeof(NOISE_PAYLOAD2)) == 0, "msg: decode noise payload");
  CHECK(p.firewall == 2 && p.has_holepunch && p.holepunch_id == 3 && p.relays_len == 1, "msg: payload holepunch info");
  CHECK(p.has_udx && p.udx_id == 0xdeadbeef && p.addresses4_len == 1 && p.relay_addresses_len == 1, "msg: payload udx/addresses");
  int n = hdht_noise_payload_encode(&p, buf, sizeof(buf));
  CHECK_BYTES(buf, n, NOISE_PAYLOAD2, "msg: re-encode noise payload");

  CHECK(hdht_noise_payload_decode(&p, NOISE_PAYLOAD1, sizeof(NOISE_PAYLOAD1)) == 0, "msg: decode payload1");
  n = hdht_noise_payload_encode(&p, buf, sizeof(buf));
  CHECK_BYTES(buf, n, NOISE_PAYLOAD1, "msg: re-encode payload1");

  hdht_handshake_msg_t hs;
  CHECK(hdht_handshake_decode(&hs, MSG_HANDSHAKE, sizeof(MSG_HANDSHAKE)) == 0 && hs.mode == 2 && hs.has_peer_address, "msg: decode handshake");
  n = hdht_handshake_encode(&hs, buf, sizeof(buf));
  CHECK_BYTES(buf, n, MSG_HANDSHAKE, "msg: re-encode handshake");

  hdht_holepunch_msg_t hp;
  CHECK(hdht_holepunch_decode(&hp, MSG_HOLEPUNCH, sizeof(MSG_HOLEPUNCH)) == 0 && hp.id == 300 && hp.payload_len == 70, "msg: decode holepunch");
  n = hdht_holepunch_encode(&hp, buf, sizeof(buf));
  CHECK_BYTES(buf, n, MSG_HOLEPUNCH, "msg: re-encode holepunch");

  hdht_holepunch_payload_t hpp;
  CHECK(hdht_holepunch_payload_decode(&hpp, MSG_HOLEPUNCH_PAYLOAD, sizeof(MSG_HOLEPUNCH_PAYLOAD)) == 0 && hpp.punching && hpp.has_token && hpp.has_remote_token, "msg: decode holepunch payload");
  n = hdht_holepunch_payload_encode(&hpp, buf, sizeof(buf));
  CHECK_BYTES(buf, n, MSG_HOLEPUNCH_PAYLOAD, "msg: re-encode holepunch payload");

  // announce signature
  uint8_t r_pk[32], r_sk[64];
  seed_keypair(r_pk, r_sk, 0x02);
  uint8_t target[32];
  hdht_hash(target, r_pk, 32);
  CHECK(memcmp(target, ANN_TARGET, 32) == 0, "announce: target");
  n = hdht_announce_encode_signed(buf, sizeof(buf), HDHT_NS_ANNOUNCE, target, ANN_NODE_ID, ANN_TOKEN, r_pk, r_sk);
  CHECK_BYTES(buf, n, ANN_VALUE, "announce: signed value");
}

int
main (void) {
  if (sodium_init() < 0) return 1;
  test_noise();
  test_messages();
  printf(failures ? "%d FAILED\n" : "all passed\n", failures);
  return failures ? 1 : 0;
}
